#include <boost/asio.hpp>
#include <chrono>
#include <iostream>

boost::asio::io_context io;
boost::asio::steady_timer timer(io, std::chrono::seconds({seconds}));
timer.async_wait([](const boost::system::error_code& error) {
    if (!error) std::cout << {message} << '\n';
});
io.run();

#include <boost/program_options.hpp>
#include <string>

namespace po = boost::program_options;
po::options_description options({caption});
options.add_options()
    ("help,h", "show help")
    ("{optionName}", po::value<std::string>()->default_value({defaultValue}), {description});
po::variables_map values;
po::store(po::parse_command_line(argc, argv, options), values);
po::notify(values);
